function DurationField({
  idPrefix,
  label,
  mode,
  years,
  months,
  date,
  onModeChange,
  onYearsChange,
  onMonthsChange,
  onDateChange,
  disabled = false,
}: {
  idPrefix: string;
  label: string;
  mode: "duration" | "date";
  years: string;
  months: string;
  date: string;
  onModeChange: (mode: "duration" | "date") => void;
  onYearsChange: (value: string) => void;
  onMonthsChange: (value: string) => void;
  onDateChange: (value: string) => void;
  disabled?: boolean;
}) {
  return (
    <div className="space-y-1 lg:col-span-2">
      <div className="flex items-center justify-between gap-2">
        <Label className="text-[10px] font-medium leading-none text-slate-700">{label}</Label>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={disabled}
          onClick={() => onModeChange(mode === "duration" ? "date" : "duration")}
          className="h-6 px-2 text-[10px] text-cyan-800"
        >
          <CalendarDays className="size-3" />
          {mode === "duration" ? "Use start month" : "Use duration"}
        </Button>
      </div>
      {mode === "date" ? (
        <Input
          id={`${idPrefix}-date`}
          type="month"
          value={date}
          onChange={(event) => onDateChange(event.target.value)}
          disabled={disabled}
          className="h-8 rounded-sm border-slate-300 bg-white px-2 text-xs focus-visible:ring-1"
        />
      ) : (
        <div className="grid grid-cols-2 gap-2">
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-years`} className="text-[10px] font-medium leading-none text-slate-700">
              Years
            </Label>
            <Input
              id={`${idPrefix}-years`}
              type="number"
              min="0"
              value={years}
              onChange={(event) => onYearsChange(event.target.value)}
              placeholder="0"
              disabled={disabled}
              className="h-8 rounded-sm border-slate-300 bg-white px-2 text-xs focus-visible:ring-1"
            />
          </div>
          <ComboField
            id={`${idPrefix}-months`}
            label="Months"
            value={months}
            onChange={onMonthsChange}
            options={MONTH_OPTIONS}
            disabled={disabled}
          />
        </div>
      )}
    </div>
  );
}

