function FinanceAccountStep({ defaultEmail, defaultName }: { defaultEmail: string; defaultName: string }) {
  const { user } = useAuth();
  const [mode, setMode] = useState<"signin" | "signup">("signup");
  const [email, setEmail] = useState(defaultEmail);
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);

  if (user) {
    return (
      <div className="flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900">
        <ShieldCheck className="size-5 shrink-0" />
        <span>
          Signed in as <strong>{user.email}</strong>. Submit to send your application.
        </span>
      </div>
    );
  }

  async function submitAccount() {
    const cleanEmail = email.trim().toLowerCase();
    if (!cleanEmail || password.length < (mode === "signup" ? 8 : 1)) {
      toast.error(
        mode === "signup"
          ? "Enter your email and a password of at least 8 characters."
          : "Enter your email and password.",
      );
      return;
    }
    setBusy(true);
    try {
      if (mode === "signup") {
        const result = await registerAccount({ data: { email: cleanEmail, password, fullName: defaultName } });
        if (result.status === "exists") {
          toast.error("An account already exists for that email. Please sign in.");
          setMode("signin");
          return;
        }
        if (result.status !== "created") {
          toast.error(result.message || "We couldn't create your account.");
          return;
        }
      }
      const { error } = await supabase.auth.signInWithPassword({ email: cleanEmail, password });
      if (error) {
        toast.error(
          error.message.toLowerCase().includes("invalid") ? "That email and password didn't work." : error.message,
        );
        return;
      }
      void linkLegacyProfile({}).catch(() => undefined);
      toast.success("You're signed in. Submit your application.");
    } catch (cause) {
      toast.error(cause instanceof Error ? cause.message : "Something went wrong.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      <div className="space-y-1.5">
        <Label htmlFor="fin-acc-email" className="text-xs font-medium text-slate-600">
          Email
        </Label>
        <Input
          id="fin-acc-email"
          type="email"
          autoComplete="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="h-12"
        />
      </div>
      <div className="space-y-1.5">
        <Label htmlFor="fin-acc-password" className="text-xs font-medium text-slate-600">
          Password
        </Label>
        <Input
          id="fin-acc-password"
          type="password"
          autoComplete={mode === "signup" ? "new-password" : "current-password"}
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              void submitAccount();
            }
          }}
          className="h-12"
        />
      </div>
      <Button
        type="button"
        onClick={() => void submitAccount()}
        disabled={busy}
        variant="outline"
        className="h-12 w-full rounded-full border-[#1473d1] font-semibold text-[#1473d1] hover:bg-[#eaf4ff]"
      >
        {busy ? "Please wait…" : mode === "signup" ? "Create account" : "Sign in"}
      </Button>
      <p className="text-center text-sm text-slate-600">
        {mode === "signup" ? "Already have an account?" : "New to MyCar?"}{" "}
        <button
          type="button"
          className="font-semibold text-[#1473d1] hover:underline"
          onClick={() => setMode(mode === "signup" ? "signin" : "signup")}
        >
          {mode === "signup" ? "Sign in" : "Create one"}
        </button>
      </p>
      <div className="rounded-lg bg-slate-50 p-3 text-[11px] leading-5 text-slate-500">
        By continuing, you agree to be contacted by My Car Business Services LLC about your application. We never sell
        your information.
      </div>
    </div>
  );
}
